import{at as e,it as t,t as n,yt as r}from"./chunks/framework.Dyi9RH6t.js";var i=JSON.parse(`{"title":"Key Terminology","description":"Learn the difference between StructuredDocument, ResourceDocument, and ReactiveDocument, and what ResourceType, ResourceKey, ResourceSchema, and Collection mean.","frontmatter":{"description":"Learn the difference between StructuredDocument, ResourceDocument, and ReactiveDocument, and what ResourceType, ResourceKey, ResourceSchema, and Collection mean."},"headers":[],"relativePath":"guides/the-manual/caching/key-terms.md","filePath":"guides/the-manual/caching/key-terms.md"}`),a={name:`guides/the-manual/caching/key-terms.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="key-terminology" tabindex="-1">Key Terminology <a class="header-anchor" href="#key-terminology" aria-label="Permalink to “Key Terminology”">​</a></h1><p>The hardest part about learning a new tool or technology is often building a correct understanding of the terminology the project uses. In this <strong><em>Warp</em>Drive</strong> is like all other projects.</p><p>As much as possible, we&#39;ve tried to name things in ways we hope you will find intuitive, or at least intuitive once the basics have sunk in. But getting the basics down is a chicken/egg paradox where sometimes you already need to understand some terminology.</p><p>By this point you should have learned about our first main-theme: <a href="./../requests/">requests</a>. This document lays out a few terms associated to the remaining main themes you&#39;ll need to know to be successful: <a href="#documents">Documents</a> and <a href="#resources">Resources</a>.</p><h2 id="documents" tabindex="-1">Documents <a class="header-anchor" href="#documents" aria-label="Permalink to “Documents”">​</a></h2><p><strong><em>Warp</em>Drive</strong> calls a few <em>tightly related</em> concepts &quot;documents&quot;.</p><ol><li><p><a href="/pr-preview/pr-11292/api/@warp-drive/core/types/request/types/StructuredDocument">StructuredDocument</a>, which is the resolved result of making a request with the <code>{ request, response, content }</code> signature.</p></li><li><p><a href="/pr-preview/pr-11292/api/@warp-drive/core/types/spec/document/types/ResourceDocument">ResourceDocument</a>, which is the <code>content</code> of a StructuredDocument typically produced by parsing the <code>body</code> of the response of a <code>fetch</code> request.</p></li><li><p><a href="/pr-preview/pr-11292/api/@warp-drive/core/reactive/types/ReactiveDocument">ReactiveDocument</a>, which is a reactive wrapper providing immutable access to the cache data for a ResourceDocument. Not all requests have a ReactiveDocument for their response.</p></li></ol><p>What&#39;s the common thread? All three are representations of a request and its result each with a distinct purpose. For this reason when cacheable they share a CacheKey (the <code>RequestKey</code>).</p><p>For requests that don&#39;t use the cache, this is about as much as you need to know. But for requests that do use the cache (most requests) there&#39;s one final important nuance: Documents don&#39;t store any resource data. When the cache receives the request response, <a href="./#resource-extraction">it will separate out resource data from the rest of the document</a>. Wait ... what&#39;s a Resource? Read on.</p><h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to “Resources”">​</a></h2><p>Resources are <strong><em>Warp</em>Drive</strong>&#39;s term for discretely identifiable data.</p><p>The most common example of a resource would be data matching a row in a database table. The table name would typically be it&#39;s <code>ResourceType</code> and it would have a <code>PrimaryKey</code>. For instance a &quot;user&quot; with id &quot;1&quot;.</p><p>Knowing both the <code>ResourceType</code> and <code>PrimaryKey</code> would allow you to lookup the row in the database. Hence - discretely identifiable.</p><p>But resources need not map to rows in a database - any named concept with a unique key value meaningful to your app&#39;s domain logic can be a resource.</p><p><strong><em>Warp</em>Drive</strong> distinguishes between documents and resources both because responses can contain zero, one, or many resources and because the same resource may be present in more than one response document.</p><p>A <code>Resource</code> has a <code>ResourceType</code> (its name, a string), <code>ResourceKey</code> (see <a href="./">caching</a>), a <code>ResourceSchema</code> (defining it&#39;s <a href="./../schemas/">fields</a>), and its reactive wrapper - a <code>ReactiveResource</code>.</p><ul><li>The <code>ResourceType</code> is the name of the <code>ResourceSchema</code></li><li>An array of resources is a <code>ResourceArray</code></li><li>The reactive wrapper for a <code>ResourceArray</code> is a <code>ReactiveResourceArray</code></li></ul><p>In a few cases you will see the term <code>Collection</code>. Generally a collection is just a list (array) of resources. We tend to use this term when the list is part of a <code>Many</code> relationship or has a similar <code>unique</code> (no repeat/duplicate values) constraint.</p>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};